import os
from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first file in `names` readable from `notes`.

    Each name is resolved relative to the directory `notes` in the current
    working directory. Names are untrusted: any name that would reach a file
    outside `notes` (via "..", an absolute path, a symlink, etc.) is treated
    as unreadable. Missing, unreadable, non-file, or undecodable entries are
    skipped. Returns "" when no name yields a readable file.
    """
    try:
        base = Path("notes").resolve()
    except (OSError, RuntimeError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            if Path(name).is_absolute():
                continue
            candidate = (base / name).resolve()
            if candidate == base or not candidate.is_relative_to(base):
                continue
            if not candidate.is_file():
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, ValueError, RuntimeError):
            continue
    return ""


@pytest.fixture
def work(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    root = tmp_path / "work"
    (root / "notes").mkdir(parents=True)
    (root / "secret.txt").write_text("SECRET", encoding="utf-8")
    (root / "notes2").mkdir()
    (root / "notes2" / "x.txt").write_text("SIBLING", encoding="utf-8")
    monkeypatch.chdir(root)
    return root


def test_returns_first_readable(work: Path) -> None:
    (work / "notes" / "b.txt").write_text("bee", encoding="utf-8")
    (work / "notes" / "c.txt").write_text("sea", encoding="utf-8")
    assert first_readable(["a.txt", "b.txt", "c.txt"]) == "bee"


def test_none_readable_and_empty_list(work: Path) -> None:
    assert first_readable(["nope.txt", "also-nope.txt"]) == ""
    assert first_readable([]) == ""


def test_parent_traversal_rejected(work: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_traversal_skipped_then_next_name_used(work: Path) -> None:
    (work / "notes" / "ok.txt").write_text("fine", encoding="utf-8")
    assert first_readable(["../secret.txt", "ok.txt"]) == "fine"


def test_absolute_path_rejected(work: Path) -> None:
    assert first_readable([str(work / "secret.txt")]) == ""
    inside = work / "notes" / "in.txt"
    inside.write_text("inside", encoding="utf-8")
    assert first_readable([str(work / "secret.txt"), "in.txt"]) == "inside"


def test_sibling_directory_with_same_prefix_rejected(work: Path) -> None:
    assert first_readable(["../notes2/x.txt"]) == ""


def test_symlink_escape_rejected(work: Path) -> None:
    link = work / "notes" / "link.txt"
    try:
        link.symlink_to(work / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert first_readable(["link.txt"]) == ""


def test_symlink_inside_notes_is_fine_or_empty_but_never_outside(work: Path) -> None:
    target = work / "notes" / "real.txt"
    target.write_text("real", encoding="utf-8")
    link = work / "notes" / "alias.txt"
    try:
        link.symlink_to(target)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert first_readable(["alias.txt"]) in ("real", "")


def test_directory_is_skipped(work: Path) -> None:
    (work / "notes" / "sub").mkdir()
    (work / "notes" / "f.txt").write_text("file", encoding="utf-8")
    assert first_readable(["sub", "f.txt"]) == "file"
    assert first_readable(["sub"]) == ""


def test_empty_and_dot_names(work: Path) -> None:
    assert first_readable(["", ".", ".."]) == ""


def test_nul_byte_name_is_skipped(work: Path) -> None:
    (work / "notes" / "g.txt").write_text("gee", encoding="utf-8")
    assert first_readable(["bad\x00name", "g.txt"]) == "gee"


def test_undecodable_file_is_skipped(work: Path) -> None:
    (work / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa")
    (work / "notes" / "t.txt").write_text("text", encoding="utf-8")
    assert first_readable(["bin.dat", "t.txt"]) == "text"


def test_file_in_subdirectory_of_notes(work: Path) -> None:
    (work / "notes" / "sub").mkdir()
    (work / "notes" / "sub" / "x.txt").write_text("deep", encoding="utf-8")
    assert first_readable(["sub/x.txt"]) == "deep"


@pytest.mark.skipif(os.name == "nt", reason="permission bits are POSIX-specific")
def test_unreadable_permissions_skipped(work: Path) -> None:
    locked = work / "notes" / "locked.txt"
    locked.write_text("locked", encoding="utf-8")
    locked.chmod(0)
    (work / "notes" / "open.txt").write_text("open", encoding="utf-8")
    try:
        if os.access(locked, os.R_OK):
            pytest.skip("running with privileges that bypass permissions")
        assert first_readable(["locked.txt", "open.txt"]) == "open"
    finally:
        locked.chmod(0o644)
